// Get all input items
const items = $input.all();

// Process each item
return items.map(item => {
  const body = item.json.body || {};

  const originalName = body.customer_name || item.json['Full Name'] || '';
  const originalPhone = body.customer_phone || item.json['Phone Number'] || '';
  const originalEmail = body.customer_email || item.json['Email Address'] || '';
  const originalLocation = body.service_location || item.json['Service Location'] || '';
  const originalServiceType = body.service_type || item.json['Service Type'] || '';
  const originalDetails = body.request_details || item.json['How can we help you?'] || '';

  const originalInput = String(originalPhone).trim();
  let cleanNumber = originalInput.replace(/\D/g, '');
  let standardizedNumber = 'incorrect format';

  if (originalInput.startsWith('+')) {
    standardizedNumber = '+' + cleanNumber;
  } else {
    if (cleanNumber.startsWith('09') && cleanNumber.length === 11) {
      standardizedNumber = '+63' + cleanNumber.substring(1);
    } else if (cleanNumber.startsWith('639') && cleanNumber.length === 12) {
      standardizedNumber = '+' + cleanNumber;
    } else if (cleanNumber.startsWith('1') && cleanNumber.length === 11) {
      standardizedNumber = '+' + cleanNumber;
    } else if (cleanNumber.length === 10) {
      if (cleanNumber.startsWith('9')) {
        standardizedNumber = '+63' + cleanNumber;
      } else {
        standardizedNumber = '+1' + cleanNumber;
      }
    } else {
      standardizedNumber = 'incorrect format';
    }
  }

  return {
    json: {
      'Full Name': originalName.trim(),
      'Phone Number': standardizedNumber,
      'Email Address': originalEmail.trim(),
      'Service Location': originalLocation.trim(),
      'Service Type': originalServiceType.trim(),
      'How can we help you?': originalDetails.trim()
    }
  };
});

const callDetails = $json.artifact?.structuredOutputs || {};
const scope = (typeof callDetails.scope_of_call === 'object' ? callDetails.scope_of_call?.result : callDetails.scope_of_call) || '';
const type = (typeof callDetails.system_type === 'object' ? callDetails.system_type?.result : callDetails.system_type) || '';
const qty = (typeof callDetails.unit_quantity === 'object' ? callDetails.unit_quantity?.result : callDetails.unit_quantity) || '';
const time = (typeof callDetails.preferred_time === 'object' ? callDetails.preferred_time?.result : callDetails.preferred_time) || '';

let jobDetails = `${scope}\n\n`;
if (type) jobDetails += `• System Type: ${type}\n`;
if (qty) jobDetails += `• Quantity: ${qty}\n`;
if (time) jobDetails += `• Preferred Time: ${time}`;

return {
  json: {
    ...$json,
    jobDetails: jobDetails.trim(),
    _vapi_urgency: (typeof callDetails.urgency === 'object' ? callDetails.urgency?.result : callDetails.urgency) || '',
    _vapi_system_type: type
  }
};

